use std::hint::black_box;

use hdrhistogram::Histogram;

const WARMUP: u64 = 10_000;
const ITERATIONS: u64 = 10_000_000;
//const ITERATIONS: u64 = 100_000;
const INNER_ITERATIONS: u64 = 10;

fn round_elapsed_time(elapsed_ns: u64) -> u64 {
    (elapsed_ns + (INNER_ITERATIONS / 2)) / INNER_ITERATIONS
}

fn measure_minstant(hist: &mut Histogram<u64>) {
    // Warmup
    for _ in 0..WARMUP {
        black_box(minstant::Instant::now());
    }

    // Measure
    for _ in 0..ITERATIONS {
        let start = minstant::Instant::now();
        for _ in 0..INNER_ITERATIONS {
            black_box(minstant::Instant::now());
        }
        let elapsed_ns = start.elapsed().as_nanos() as u64;
        hist.record(round_elapsed_time(elapsed_ns)).unwrap();
    }
}

fn measure_instant(hist: &mut Histogram<u64>) {
    // Warmup
    for _ in 0..WARMUP {
        black_box(std::time::Instant::now());
    }

    // Measure using minstant as the reference timer
    for _ in 0..ITERATIONS {
        let start = minstant::Instant::now();
        for _ in 0..INNER_ITERATIONS {
            black_box(std::time::Instant::now());
        }
        let elapsed_ns = start.elapsed().as_nanos() as u64;
        hist.record(round_elapsed_time(elapsed_ns)).unwrap();
    }
}

fn print_histogram(name: &str, hist: &Histogram<u64>) {
    println!("{name} ({} iterations)", ITERATIONS * INNER_ITERATIONS);
    println!("  min      {:>6} ns", hist.min());
    println!("  p1       {:>6} ns", hist.value_at_quantile(0.01));
    println!("  p10      {:>6} ns", hist.value_at_quantile(0.10));
    println!("  p20      {:>6} ns", hist.value_at_quantile(0.20));
    println!("  p30      {:>6} ns", hist.value_at_quantile(0.30));
